import{_ as l,o as e,c as t,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const u=JSON.parse('{"title":"CDS Hammer (Day 2) - OSD (Tiering): Reduce R/W Latencies on Cache Tier Miss","description":"","frontmatter":{"title":"CDS Hammer (Day 2) - OSD (Tiering): Reduce R/W Latencies on Cache Tier Miss","date":"2014-10-30T00:00:00.000Z","updated":"2014-10-31T00:00:00.000Z","tags":["Ceph","分布式存储","优化","Cache Tier","R/W Latency"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2014/CDS_Hammer_Day_2_-_OSD_Tiering_-_Reduce_R_W_Latencies_on_Cache_Tier_Miss.md","filePath":"posts/2014/CDS_Hammer_Day_2_-_OSD_Tiering_-_Reduce_R_W_Latencies_on_Cache_Tier_Miss.md","lastUpdated":1780459816000}'),_={name:"posts/2014/CDS_Hammer_Day_2_-_OSD_Tiering_-_Reduce_R_W_Latencies_on_Cache_Tier_Miss.md"};function r(o,i,n,a,p,g){return e(),t("div",null,[...i[0]||(i[0]=[s('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议主题</strong>： Ceph 分布式存储优化讨论</p><p><strong>会议时间</strong>： 2023年11月（具体日期未提及）</p><p><strong>参会人员</strong>： 多位 Ceph 开发人员</p><p><strong>会议内容</strong>：</p><p><strong>一、讨论要点</strong></p><ol><li><p><strong>读取优化</strong>：</p><ul><li>当前代码在进行读取操作时，若缓存缺失，会先将对象提升至所有 OSD 实例，然后再进行复制。会议提出首先服务读取请求，然后在提升操作完成后进行复制，以减少读取延迟。</li><li>针对异步读取，建议在读取操作可以完全由一个数据块满足时，使用该策略。</li></ul></li><li><p><strong>写入优化</strong>：</p><ul><li>在写入操作中，可以将提升的对象数据复制到所有 OSD 实例，并更新对象属性。</li><li>建议避免进行不必要的复制操作，以提高效率。对于完全覆盖对象的情况，可以只提升对象属性，而不是数据。</li></ul></li><li><p><strong>复制优化</strong>：</p><ul><li>在复制操作中，可以将提升的对象数据复制到所有 OSD 实例，并更新对象属性。</li><li>建议避免进行不必要的复制操作，以提高效率。</li></ul></li></ol><p><strong>二、关键决策</strong></p><ol><li><p><strong>读取优化</strong>：</p><ul><li>实施异步读取策略，并在满足条件时使用读取优化策略。</li><li>评估读取优化策略的有效性，并根据实际工作负载进行调整。</li></ul></li><li><p><strong>写入优化</strong>：</p><ul><li>实施写入优化策略，避免不必要的复制操作。</li><li>评估写入优化策略的有效性，并根据实际工作负载进行调整。</li></ul></li><li><p><strong>复制优化</strong>：</p><ul><li>实施复制优化策略，避免不必要的复制操作。</li><li>评估复制优化策略的有效性，并根据实际工作负载进行调整。</li></ul></li></ol><p><strong>三、后续行动计划</strong></p><ol><li><p><strong>读取优化</strong>：</p><ul><li>实现异步读取策略。</li><li>评估读取优化策略的有效性，并根据实际工作负载进行调整。</li></ul></li><li><p><strong>写入优化</strong>：</p><ul><li>实现写入优化策略。</li><li>评估写入优化策略的有效性，并根据实际工作负载进行调整。</li></ul></li><li><p><strong>复制优化</strong>：</p><ul><li>实现复制优化策略。</li><li>评估复制优化策略的有效性，并根据实际工作负载进行调整。</li></ul></li><li><p><strong>数据收集</strong>：</p><ul><li>使用 Adam 开发的 RBD 跟踪捕获工具收集实际工作负载数据。</li><li>分析数据，以确定读取优化和写入优化策略的有效性。</li></ul></li></ol><p><strong>四、其他</strong></p><ol><li>会议中提到了 RBD 的跟踪捕获工具，该工具可以捕获实际工作负载的跟踪数据。</li><li>会议讨论了 RBD 的写入操作，包括完整覆盖对象的情况。</li><li>会议讨论了 Ceph 的优化策略，包括异步读取、写入优化和复制优化。</li></ol>',13)])])}const d=l(_,[["render",r]]);export{u as __pageData,d as default};
